class M(type):
 def __instancecheck__(cls,obj):
  print("never")
  return False
class A(metaclass=M): pass
print(isinstance(A(),A))

class M(type):
 def __instancecheck__(cls,obj): return True
class A(metaclass=M):
 def __instancecheck__(self,obj): return False
print(isinstance(7,A))

class M(type):
 @staticmethod
 def __instancecheck__(obj): return obj==7
class A(metaclass=M): pass
print(isinstance(7,A))

class M(type):
 @classmethod
 def __instancecheck__(meta,obj): return meta is M
class A(metaclass=M): pass
print(isinstance(7,A))

class D:
 def __get__(self,obj,owner):
  print(obj.__name__,owner.__name__)
  def check(value): return value==7
  return check
class M(type): __instancecheck__=D()
class A(metaclass=M): pass
print(isinstance(7,A))

class M(type):
 @property
 def __instancecheck__(cls):
  print(cls.__name__)
  return lambda obj: obj==7
class A(metaclass=M): pass
print(isinstance(7,A))

class Truth:
 def __bool__(self):
  print("truth")
  return True
class M(type):
 def __instancecheck__(cls,obj): return Truth()
class A(metaclass=M): pass
print(isinstance(7,A))

